def choose_move(observation):
    def is_num(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    def clamp_step(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def to_pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return (v[0], v[1])
        if isinstance(v, dict):
            for kx, ky in (("x", "y"), ("col", "row"), ("cx", "cy")):
                if kx in v and ky in v and is_num(v.get(kx)) and is_num(v.get(ky)):
                    return (v.get(kx), v.get(ky))
        return None

    def find_first_pos(obj, keys):
        if isinstance(obj, dict):
            for k in keys:
                if k in obj:
                    p = to_pos(obj.get(k))
                    if p is not None:
                        return p
            for vv in obj.values():
                p = find_first_pos(vv, keys)
                if p is not None:
                    return p
        elif isinstance(obj, (list, tuple)):
            for vv in obj:
                p = find_first_pos(vv, keys)
                if p is not None:
                    return p
        return None

    def collect_positions(obj, out, limit=256):
        if len(out) >= limit:
            return
        p = to_pos(obj)
        if p is not None:
            out.append(p)
            return
        if isinstance(obj, dict):
            for vv in obj.values():
                collect_positions(vv, out, limit)
                if len(out) >= limit:
                    return
        elif isinstance(obj, (list, tuple)):
            for vv in obj:
                collect_positions(vv, out, limit)
                if len(out) >= limit:
                    return

    def get_section(obs, *names):
        if isinstance(obs, dict):
            for n in names:
                if n in obs:
                    return obs.get(n)
        return None

    me = find_first_pos(observation, ("self", "agent", "player", "unit", "robot", "avatar", "me", "position", "pos"))
    if me is None:
        me = find_first_pos(get_section(observation, "state", "env", "observation", "info"), ("self", "agent", "player", "unit", "robot", "avatar", "me", "position", "pos"))
    if me is None:
        return [0, 0]
    x, y = me

    resources = []
    enemies = []
    targets = []
    territory = []
    for key in ("resources", "resource", "food", "foods", "targets", "target", "goals", "goal", "enemy", "enemies", "opponents", "opponent", "prey", "territory", "cells", "grid", "map"):
        section = get_section(observation, key)
        if section is not None:
            if key in ("enemy", "enemies", "opponents", "opponent", "prey"):
                collect_positions(section, enemies)
            elif key in ("resources", "resource", "food", "foods"):
                collect_positions(section, resources)
            elif key in ("territory", "cells", "grid", "map"):
                collect_positions(section, territory)
            else:
                collect_positions(section, targets)

    # Heuristic target selection
    all_targets = []
    if resources:
        all_targets += resources
    if targets:
        all_targets += targets
    if territory:
        all_targets += territory

    def nearest(points):
        best = None
        best_d = None
        for px, py in points:
            d = abs(px - x) + abs(py - y)
            if best_d is None or d < best_d:
                best_d = d
                best = (px, py)
        return best, best_d

    near_enemy, enemy_d = nearest(enemies) if enemies else (None, None)
    near_res, res_d = nearest(resources) if resources else (None, None)
    near_any, any_d = nearest(all_targets) if all_targets else (None, None)

    moves = [(-1, 0), (1, 0), (0, -1), (0, 1), (0, 0)]
    best_move = (0, 0)
    best_score = None

    for dx, dy in moves:
        nx, ny = x + dx, y + dy
        score = 0

        if near_res is not None:
            score -= abs(near_res[0] - nx) + abs(near_res[1] - ny) * 2
        elif near_any is not None:
            score -= abs(near_any[0] - nx) + abs(near_any[1] - ny) * 2

        if near_enemy is not None:
            dist = abs(near_enemy[0] - nx) + abs(near_enemy[1] - ny)
            if enemy_d is not None and enemy_d <= 3:
                score += dist * 3
            else:
                score -= max(0, 4 - dist)

        # Prefer movement over idle when useful
        if dx != 0 or dy != 0:
            score += 0.1

        # Mild centrality/straight-line stability
        score -= abs(dx) * 0.01 + abs(dy) * 0.01

        if best_score is None or score > best_score:
            best_score = score
            best_move = (dx, dy)

    return [clamp_step(best_move[0]), clamp_step(best_move[1])]

